#![no_std]
#![no_main]

use rmk::macros::rmk_keyboard;
mod display;
mod display_policy;
mod rgb;
mod rgb_policy;

// Vial config is automatically generated by `build.rs`, according to `vial.json`
// Please put `vial.json` at your project's root
#[rmk_keyboard]
mod keyboard {
    #[register_processor]
    fn layer_rgb() -> crate::rgb::LayerRgb<esp_hal::spi::master::Spi<'static, esp_hal::Blocking>> {
        let spi = esp_hal::spi::master::Spi::new(
            p.SPI2,
            esp_hal::spi::master::Config::default()
                .with_frequency(esp_hal::time::Rate::from_hz(2_400_000))
                .with_mode(esp_hal::spi::Mode::_0),
        ).expect("RGB SPI configuration").with_mosi(p.GPIO13);
        crate::rgb::LayerRgb::new(spi)
    }
}
